mapper.sql:
o.deleted=0 and ${scope}

    and (o.order_no like concat('%', #{keyword}, '%'))


    and o.status=#{status}

mapper.update:
update po_purchase_order
set supplier_id=#{supplierId}, delivery_date=#{deliveryDate}, tax_rate=#{taxRate},
    total_amount=#{totalAmount}, terms=#{terms,jdbcType=VARCHAR}, status='DRAFT',
    process_instance_id=null, cancellation_reason=null, updated_by=#{userId}
where id=#{id}

update po_purchase_order
set supplier_id=#{supplierId}, delivery_date=#{deliveryDate}, tax_rate=#{taxRate},
    total_amount=#{totalAmount}, terms=#{terms,jdbcType=VARCHAR}, status='DRAFT',
    process_instance_id=null, updated_by=#{userId}
where id=#{id}

update po_purchase_order
set status=#{status}, process_instance_id=#{processInstanceId}, updated_by=#{userId}
where id=#{id}

update po_purchase_order
set status='CANCELLED', cancellation_reason=#{reason}, process_instance_id=null, updated_by=#{userId}
where id=#{id}

update po_purchase_order
set status='CLOSED', closed_at=utc_timestamp(6), updated_by=#{userId}
where id=#{id}
